package org.newsclub.net.unix;

import java.io.FileDescriptor;
import java.io.IOException;
import java.net.SocketAddress;
import java.net.SocketException;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * The core functionality of file descriptor based I/O.
 * 
 * @author Christian Kohlschütter
 */
class AFUNIXCore extends CleanableState {
  @SuppressWarnings("PMD.UseDiamondOperator") // not in Java 7
  private static final ThreadLocal<ByteBuffer> DATAGRAMPACKET_BUFFER_TL =
      new ThreadLocal<ByteBuffer>();

  private static final int DATAGRAMPACKET_BUFFER_MIN_CAPACITY = 8192;
  private static final int DATAGRAMPACKET_BUFFER_MAX_CAPACITY = 1 * 1024 * 1024;

  private final AtomicBoolean closed = new AtomicBoolean(false);

  protected final FileDescriptor fd = new FileDescriptor();
  protected final AncillaryDataSupport ancillaryDataSupport;

  protected AFUNIXCore(Object observed, AncillaryDataSupport ancillaryDataSupport) {
    super(observed);
    this.ancillaryDataSupport = ancillaryDataSupport;
  }

  protected AFUNIXCore(Object observed) {
    this(observed, null);
  }

  @Override
  protected void doClean() {
    if (fd != null && fd.valid()) {
      try {
        doClose();
      } catch (IOException e) {
        // ignore
      }
    }
    if (ancillaryDataSupport != null) {
      ancillaryDataSupport.close();
    }
  }

  protected boolean isClosed() {
    return closed.get();
  }

  protected void doClose() throws IOException {
    NativeUnixSocket.close(fd);
    closed.set(true);
  }

  protected FileDescriptor validFdOrException() throws SocketException {
    FileDescriptor fdesc = validFd();
    if (fdesc == null) {
      closed.set(true);
      throw new SocketException("Not open");
    }
    return fdesc;
  }

  protected synchronized FileDescriptor validFd() {
    if (isClosed()) {
      return null;
    }
    FileDescriptor descriptor = this.fd;
    if (descriptor != null) {
      if (descriptor.valid()) {
        return descriptor;
      }
    }
    return null;
  }

  int read(ByteBuffer dst) throws IOException {
    return read(dst, null, 0);
  }

  int read(ByteBuffer dst, ByteBuffer socketAddressBuffer, int options) throws IOException {
    int remaining = dst.remaining();
    if (remaining == 0) {
      return 0;
    }
    FileDescriptor fdesc = validFdOrException();

    ByteBuffer buf;
    if (dst.isDirect()) {
      buf = dst;
    } else {
      buf = getThreadLocalDirectByteBuffer(remaining);
      remaining = Math.min(remaining, buf.remaining());
    }

    int pos = dst.position();

    int count = NativeUnixSocket.receive(fdesc, buf, pos, remaining, socketAddressBuffer, options,
        ancillaryDataSupport, 0);
    if (buf != dst) { // NOPMD
      buf.limit(count);
      dst.put(buf);
    } else {
      if (count < 0) {
        throw new IllegalStateException();
      }
      dst.position(pos + count);
    }
    return count;
  }

  int write(ByteBuffer src) throws IOException {
    return write(src, null, 0);
  }

  int write(ByteBuffer src, SocketAddress target, int options) throws IOException {
    int remaining = src.remaining();
    if (remaining == 0) {
      return 0;
    }

    FileDescriptor fdesc = validFdOrException();
    ByteBuffer addressTo;
    if (target == null) {
      addressTo = null;
    } else {
      addressTo = AFUNIXSocketAddress.SOCKETADDRESS_BUFFER_TL.get();
      AFUNIXSocketAddress.unwrapAddressDirectBufferInternal(addressTo, target);
    }

    // accept "send buffer overflow" as packet loss
    // and don't retry (which would slow things down quite a bit)
    options |= NativeUnixSocket.OPT_NON_BLOCKING;

    ByteBuffer buf;
    if (src.isDirect()) {
      buf = src;
    } else {
      buf = getThreadLocalDirectByteBuffer(remaining);
      remaining = Math.min(remaining, buf.remaining());
      buf.put(src);
      buf.position(0);
    }
    int pos = buf.position();

    int written = NativeUnixSocket.send(fdesc, buf, pos, remaining, addressTo, options,
        ancillaryDataSupport);
    if (written > 0) {
      src.position(pos + written);
    }

    return written;
  }

  ByteBuffer getThreadLocalDirectByteBuffer(int capacity) {
    if (capacity > DATAGRAMPACKET_BUFFER_MAX_CAPACITY) {
      capacity = DATAGRAMPACKET_BUFFER_MAX_CAPACITY;
    } else if (capacity < DATAGRAMPACKET_BUFFER_MIN_CAPACITY) {
      capacity = DATAGRAMPACKET_BUFFER_MIN_CAPACITY;
    }
    ByteBuffer datagramPacketBuffer = DATAGRAMPACKET_BUFFER_TL.get();
    if (datagramPacketBuffer == null || capacity > datagramPacketBuffer.capacity()) {
      datagramPacketBuffer = ByteBuffer.allocateDirect(capacity);
      DATAGRAMPACKET_BUFFER_TL.set(datagramPacketBuffer);
    }
    datagramPacketBuffer.clear();
    return datagramPacketBuffer;
  }

  void implConfigureBlocking(boolean block) throws IOException {
    NativeUnixSocket.configureBlocking(validFdOrException(), block);
  }
}

}

@Override
protected OutputStream getOutputStream() throws IOException {
  if (!connected && !isBound()) {
    throw new IOException("Not connected/not bound");
  }
  core.validFdOrException();
  return out;
}

@Override
protected void listen(int backlog) throws IOException {
  FileDescriptor fdesc = core.validFdOrException();
  if (backlog <= 0) {
    backlog = 50;
  }
  NativeUnixSocket.listen(fdesc, backlog);
}

@Override
protected boolean supportsUrgentData() {
  // We don't really support it
  return false;
}

@Override
protected void sendUrgentData(int data) throws IOException {
  throw new UnsupportedOperationException();
}

private final class AFUNIXInputStream extends InputStream {
  private volatile boolean streamClosed = false;
  private boolean eofReached = false;

  @Override
  public int read(byte[] buf, int off, int len) throws IOException {
    if (streamClosed) {
      throw new IOException("This InputStream has already been closed.");
    }
    FileDescriptor fdesc = core.validFdOrException();
    if (len == 0) {
      return 0;
    } else if (off < 0 || len < 0 || (len > buf.length - off)) {
      throw new IndexOutOfBoundsException();
    }

    return NativeUnixSocket.read(fdesc, buf, off, len, ancillaryDataSupport);
  }

  @Override
  public int read() throws IOException {
    FileDescriptor fdesc = core.validFdOrException();

    if (eofReached) {
      return -1;
    }
    int byteRead = NativeUnixSocket.read(fdesc, null, 0, 1, ancillaryDataSupport);
    if (byteRead < 0) {
      eofReached = true;
      return -1;
    } else {
      return byteRead;
    }
  }

  @Override
  public synchronized void close() throws IOException {
    streamClosed = true;
    FileDescriptor fdesc = core.validFd();
    if (fdesc != null) {
      NativeUnixSocket.shutdown(fdesc, SHUT_RD);
    }

    closedInputStream = true;
    checkClose();
  }

  @Override
  public int available() throws IOException {
    if (streamClosed) {
      throw new IOException("This InputStream has already been closed.");
    }

    return AFUNIXSocketImpl.this.available();
  }
}

private static boolean checkWriteInterruptedException(int bytesTransferred)
    throws InterruptedIOException {
  if (Thread.interrupted()) {
    InterruptedIOException ex = new InterruptedIOException("Thread interrupted during write");
    ex.bytesTransferred = bytesTransferred;
    Thread.currentThread().interrupt();
    throw ex;
  }
  return true;
}

private final class AFUNIXOutputStream extends OutputStream {
  private volatile boolean streamClosed = false;

  @Override
  public void write(int oneByte) throws IOException {
    FileDescriptor fdesc = core.validFdOrException();

    int written;
    do {
      written = NativeUnixSocket.write(fdesc, null, oneByte, 1, ancillaryDataSupport);
      if (written != 0) {
        break;
      }
    } while (checkWriteInterruptedException(0));
  }

  @Override
  public void write(byte[] buf, int off, int len) throws IOException {
    if (streamClosed) {
      throw new SocketException("This OutputStream has already been closed.");
    }
    if (len < 0 || off < 0 || len > buf.length - off) {
      throw new IndexOutOfBoundsException();
    }
    FileDescriptor fdesc = core.validFdOrException();
    if (len == 0) {
      return;
    }

    int writtenTotal = 0;

    do {
      final int written = NativeUnixSocket.write(fdesc, buf, off, len, ancillaryDataSupport);
      if (written < 0) {
        throw new IOException("Unspecific error while writing");
      }

      len -= written;
      off += written;
      writtenTotal += written;
    } while (len > 0 && checkWriteInterruptedException(writtenTotal));
  }

  @Override
  public synchronized void close() throws IOException {
    if (streamClosed) {
      return;
    }
    streamClosed = true;
    FileDescriptor fdesc = core.validFd();
    if (fdesc != null) {
      NativeUnixSocket.shutdown(fdesc, SHUT_WR);
    }
    closedOutputStream = true;
    checkClose();
  }
}

@Override
public String toString() {
  return super.toString() + "[fd=" + fd + "; addr=" + this.core.socketAddress + "; connected="
      + connected + "; bound=" + bound + "]";
}

private static int expectInteger(Object value) throws SocketException {
  try {
    return (Integer) value;
  } catch (final ClassCastException e) {
    throw (SocketException) new SocketException("Unsupported value: " + value).initCause(e);
  } catch (final NullPointerException e) {
    throw (SocketException) new SocketException("Value must not be null").initCause(e);
  }

