import org.newsclub.net.unix.AFUNIXServerSocket;
import org.newsclub.net.unix.AFUNIXSocket;
import org.newsclub.net.unix.AFUNIXSocketAddress;
import java.io.InputStream;
import java.net.SocketTimeoutException;
import java.nio.file.Files;
import java.nio.file.Path;

public class Repro {
    public static void main(String[] args) throws Exception {
        AFUNIXServerSocket server = AFUNIXServerSocket.newInstance();
        Path temp = Files.createTempFile("repro", ".sock");
        Files.delete(temp);
        final AFUNIXSocketAddress address = new AFUNIXSocketAddress(temp.toFile());
        server.bind(address);

        // client connects but never sends
        final AFUNIXSocket client = AFUNIXSocket.newInstance();
        class C extends Thread {
            public void run() {
                try {
                    AFUNIXSocket s = AFUNIXSocket.newInstance();
                    s.connect(address);
                    Thread.sleep(10000);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
        // Simpler: use the accepted socket as the one with timeout; the peer (client) sends nothing
        final AFUNIXSocket clientConn = AFUNIXSocket.newInstance();
        new Thread(() -> {
            try { clientConn.connect(address); Thread.sleep(20000); } catch (Exception e) {}
        }).start();

        final AFUNIXSocket serverSocket = server.accept();
        System.out.println("Accepted");
        serverSocket.setSoTimeout(2000);
        byte[] buf = new byte[8192];
        InputStream in = serverSocket.getInputStream();
        long start = System.currentTimeMillis();
        try {
            int read = in.read(buf);
            long elapsed = System.currentTimeMillis() - start;
            System.out.println("read returned " + read + " after " + elapsed + " ms (no exception)");
        } catch (SocketTimeoutException e) {
            long elapsed = System.currentTimeMillis() - start;
            System.out.println("SocketTimeoutException after " + elapsed + " ms");
        } catch (Exception e) {
            long elapsed = System.currentTimeMillis() - start;
            System.out.println("OTHER exception " + e.getClass().getName() + " after " + elapsed + " ms: " + e.getMessage());
        }
        System.exit(0);
    }
}
